// ToTonyIR converts Says to a Tony IR node.
func (s *Says) ToTonyIR(opts ...gomap.MapOption) (*ir.Node, error) {
	if s == nil {
		return ir.Null(), nil
	}
	var node *ir.Node
	var err error
	_ = node // suppress unused variable error
	_ = err  // suppress unused variable error

	// Create IR object map
	irMap := make(map[string]*ir.Node)

	// Field: Root
	irMap["root"] = ir.FromString(string(s.Root))

	// Field: Owns
	if len(s.Owns) > 0 {
		slice := make([]*ir.Node, len(s.Owns))
		for i, v := range s.Owns {
			node, err = v.ToTonyIR(opts...)
			if err != nil {
				return nil, fmt.Errorf("failed to convert slice element %d: %w", i, err)
			}
			slice[i] = node
		}
		irMap["owns"] = ir.FromSlice(slice)
	}

	return ir.FromMap(irMap), nil
}

// FromTonyIR populates Says from a Tony IR node.
func (s *Says) FromTonyIR(node *ir.Node, opts ...gomap.UnmapOption) error {
	if node == nil {
		return nil
	}

	// Unwrap CommentType nodes to get the actual data node
	if node.Type == ir.CommentType {
		if len(node.Values) > 0 {
			node = node.Values[0]
		} else {
			return nil
		}
	}

	if node.Type == ir.NullType {
		return nil
	}
	if node.Type != ir.ObjectType {
		return fmt.Errorf("expected map for Says, got %v", node.Type)
	}

	for i, fieldName := range node.Fields {
		fieldNode := node.Values[i]
		// Unwrap CommentType for type checking (preserve original for *ir.Node fields)
		fieldNodeUnwrapped := fieldNode
		if fieldNodeUnwrapped.Type == ir.CommentType && len(fieldNodeUnwrapped.Values) > 0 {
			fieldNodeUnwrapped = fieldNodeUnwrapped.Values[0]
		}
		switch fieldName.String {
		case "root":
			// Field: Root
			if fieldNodeUnwrapped.Type != ir.StringType {
				return fmt.Errorf("field %q: expected string, got %v", "root", fieldNodeUnwrapped.Type)
			}
			s.Root = string(fieldNodeUnwrapped.String)
		case "owns":
			// Field: Owns
			if fieldNodeUnwrapped.Type == ir.ArrayType {
				slice := make([]Own, len(fieldNodeUnwrapped.Values))
				for i, v := range fieldNodeUnwrapped.Values {
					elem := Own{}
					if err := elem.FromTonyIR(v, opts...); err != nil {
						return fmt.Errorf("failed to convert slice element %d: %w", i, err)
					}
					slice[i] = elem
				}
				s.Owns = slice
			} else {
				return fmt.Errorf("%s: expected array, got %v", "field \"owns\"", fieldNodeUnwrapped.Type)
			}
		default:
			if gomap.IsStrict(opts...) {
				return fmt.Errorf("unknown field %q for Says", fieldName.String)
			}
		}
	}

	return nil
}

